// Generate candle data from a seed for the dashboard chart.
function gtBars(seed, n = 60) {
  const out = [];
  let v = 50;
  let r = seed * 9301;
  for (let i = 0; i < n; i++) {
    r = (r * 9301 + 49297) % 233280;
    const rand = r / 233280;
    const delta = (rand - 0.5) * 6 + Math.sin(i * 0.18) * 0.4;
    const o = v;
    v += delta;
    const c = v;
    const h = Math.max(o, c) + rand * 1.6;
    const l = Math.min(o, c) - rand * 1.6;
    out.push({ o, h, l, c, up: c >= o });
  }
  return out;
}

// Build an SVG path string from a normalized series.
function gtSpark(arr, w, h, pad = 2) {
  const n = arr.length;
  const stepX = (w - pad * 2) / (n - 1);
  return arr.map((v, i) => {
    const x = pad + i * stepX;
    const y = h - pad - v * (h - pad * 2);
    return `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
}

